def parse_http_request(raw_request: str):
    if not raw_request or '\r\n' not in raw_request:
        return None

    try:
        parts = raw_request.split('\r\n\r\n', 1)
        header_section = parts[0]
        body = parts[1] if len(parts) > 1 and parts[1] else None

        lines = header_section.split('\r\n')
        request_line = lines[0].split(' ')

        if len(request_line) != 3:
            return None

        method = request_line[0]
        path = request_line[1]
        version = request_line[2].replace('HTTP/', '')

        headers = {}
        for line in lines[1:]:
            if ':' in line:
                key, value = line.split(':', 1)
                headers[key.strip().lower()] = value.strip()

        return {
            'method': method,
            'path': path,
            'version': version,
            'headers': headers,
            'body': body
        }
    except Exception:
        return None

