function parseHttpRequest(rawRequest) {
  if (!rawRequest || !rawRequest.includes('\r\n')) return null;

  try {
    const [headerSection, ...bodyParts] = rawRequest.split('\r\n\r\n');
    const body = bodyParts.join('\r\n\r\n') || null;

    const lines = headerSection.split('\r\n');
    const [method, path, httpVersion] = lines[0].split(' ');

    if (!method || !path || !httpVersion) return null;

    const version = httpVersion.replace('HTTP/', '');
    const headers = {};

    for (let i = 1; i < lines.length; i++) {
      const colonIdx = lines[i].indexOf(':');
      if (colonIdx > 0) {
        const key = lines[i].slice(0, colonIdx).trim().toLowerCase();
        const value = lines[i].slice(colonIdx + 1).trim();
        headers[key] = value;
      }
    }

    return { method, path, version, headers, body };
  } catch (e) {
    return null;
  }
}
